import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import io, base64, os
from datetime import datetime

# ── Load & parse ──────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['recorded_at'] = pd.to_datetime(df['recorded_at'], utc=True)
df['source_updated_at'] = pd.to_datetime(df['source_updated_at'], utc=True)
df['update_lag_hours'] = (df['recorded_at'] - df['source_updated_at']).dt.total_seconds() / 3600

# ── Helper: embed chart ───────────────────────────────────────
def fig_to_base64(fig, dpi=150):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', dpi=dpi, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode()
    plt.close(fig)
    return b64

FUEL_LABELS = {
    'E10': 'E10 (Standard Unleaded)',
    'E5': 'E5 (Super Unleaded)',
    'B7_STANDARD': 'B7 Standard Diesel',
    'B7_PREMIUM': 'B7 Premium Diesel',
    'B10': 'B10 Diesel',
}
FUEL_ORDER = ['E10', 'E5', 'B7_STANDARD', 'B7_PREMIUM', 'B10']
fuel_types_present = [f for f in FUEL_ORDER if f in df['fuel_type'].unique()]
PALETTE = {'E10': '#2196F3', 'E5': '#4CAF50', 'B7_STANDARD': '#FF9800', 'B7_PREMIUM': '#E91E63', 'B10': '#9C27B0'}

# ── Section 1: Overview stats ─────────────────────────────────
total_records = len(df)
unique_stations = df['node_id'].nunique()
n_fuel_types = df['fuel_type'].nunique()
date_min = df['recorded_at'].min().strftime('%d %B %Y')
date_max = df['recorded_at'].max().strftime('%d %B %Y')
fuel_type_counts = df['fuel_type'].value_counts()

# ── Section 2: Price distribution by fuel type ────────────────
price_stats = df.groupby('fuel_type')['price_pence'].agg(
    ['count', 'mean', 'median', 'std', 'min', 'max',
     lambda x: x.quantile(0.25),
     lambda x: x.quantile(0.75)]
).rename(columns={'<lambda_0>': 'Q1', '<lambda_1>': 'Q3'})
price_stats = price_stats.reindex([f for f in FUEL_ORDER if f in price_stats.index])
price_stats['IQR'] = price_stats['Q3'] - price_stats['Q1']
price_stats['range'] = price_stats['max'] - price_stats['min']

# Box plot
fig_box, ax_box = plt.subplots(figsize=(10, 5.5))
data_for_box = [df[df['fuel_type'] == ft]['price_pence'].values for ft in fuel_types_present]
bp = ax_box.boxplot(data_for_box, patch_artist=True, widths=0.55,
                    medianprops=dict(color='black', linewidth=1.5),
                    flierprops=dict(marker='.', markersize=3, alpha=0.3))
for patch, ft in zip(bp['boxes'], fuel_types_present):
    patch.set_facecolor(PALETTE[ft])
    patch.set_alpha(0.7)
ax_box.set_xticklabels([FUEL_LABELS.get(ft, ft) for ft in fuel_types_present], fontsize=9)
ax_box.set_ylabel('Price (pence per litre)', fontsize=10)
ax_box.set_title('Price Distribution by Fuel Type', fontsize=12, fontweight='bold')
ax_box.yaxis.set_major_formatter(mticker.FormatStrFormatter('%.0f'))
ax_box.grid(axis='y', alpha=0.3)
fig_box.tight_layout()
box_b64 = fig_to_base64(fig_box)

# Violin plot
fig_vio, ax_vio = plt.subplots(figsize=(10, 5.5))
parts = ax_vio.violinplot([df[df['fuel_type'] == ft]['price_pence'].values for ft in fuel_types_present],
                           positions=range(len(fuel_types_present)), showmedians=True, showextrema=True)
for i, (pc, ft) in enumerate(zip(parts['bodies'], fuel_types_present)):
    pc.set_facecolor(PALETTE[ft])
    pc.set_alpha(0.6)
parts['cmedians'].set_color('black')
parts['cmedians'].set_linewidth(1.5)
ax_vio.set_xticks(range(len(fuel_types_present)))
ax_vio.set_xticklabels([FUEL_LABELS.get(ft, ft) for ft in fuel_types_present], fontsize=9)
ax_vio.set_ylabel('Price (pence per litre)', fontsize=10)
ax_vio.set_title('Price Density Distribution by Fuel Type', fontsize=12, fontweight='bold')
ax_vio.yaxis.set_major_formatter(mticker.FormatStrFormatter('%.0f'))
ax_vio.grid(axis='y', alpha=0.3)
fig_vio.tight_layout()
vio_b64 = fig_to_base64(fig_vio)

# ── Section 3: Price spread & competitiveness ─────────────────
# IQR bar chart
fig_iqr, ax_iqr = plt.subplots(figsize=(9, 5))
x_pos = range(len(fuel_types_present))
iqr_vals = [price_stats.loc[ft, 'IQR'] for ft in fuel_types_present]
range_vals = [price_stats.loc[ft, 'range'] for ft in fuel_types_present]
bars1 = ax_iqr.bar([p - 0.18 for p in x_pos], iqr_vals, width=0.35,
                    color=[PALETTE[ft] for ft in fuel_types_present], alpha=0.8, label='IQR (p25–p75)')
bars2 = ax_iqr.bar([p + 0.18 for p in x_pos], range_vals, width=0.35,
                    color=[PALETTE[ft] for ft in fuel_types_present], alpha=0.4, label='Full Range (min–max)')
ax_iqr.set_xticks(list(x_pos))
ax_iqr.set_xticklabels([FUEL_LABELS.get(ft, ft) for ft in fuel_types_present], fontsize=9)
ax_iqr.set_ylabel('Pence per litre', fontsize=10)
ax_iqr.set_title('Price Spread: IQR vs Full Range by Fuel Type', fontsize=12, fontweight='bold')
ax_iqr.legend(fontsize=9)
ax_iqr.grid(axis='y', alpha=0.3)
